from typing import List
import math

class Solution:

    def get_1d_pos(self, x, y, side):
        if y == 0:
            return x
        elif x == side:
            return side + y
        elif y == side:
            return 2 * side + (side - x)
        else:  # x == 0
            return 3 * side + (side - y)

    def can_place(self, mid, k, side, positions):
        n = len(positions)
        per = 4 * side

        # Duplicate positions (circular -> linear)
        arr = positions + [p + per for p in positions]

        # next[i] = smallest j such that arr[j] >= arr[i] + mid
        nxt = [0] * (2 * n)
        j = 0
        for i in range(2 * n):
            if j < i:
                j = i
            while j < 2 * n and arr[j] < arr[i] + mid:
                j += 1
            nxt[i] = j

        # Binary lifting table
        LOG = math.ceil(math.log2(k)) + 1
        jump = [nxt]
        for _ in range(1, LOG):
            prev = jump[-1]
            curr = [0] * (2 * n)
            for i in range(2 * n):
                ni = prev[i]
                curr[i] = prev[ni] if ni < 2 * n else 2 * n
            jump.append(curr)

        # Try each start point among first n
        for start in range(n):
            idx = start
            steps = k - 1  # already placed at start

            bit = 0
            while steps > 0:
                if steps & 1:
                    idx = jump[bit][idx]
                    if idx >= start + n:
                        break
                steps >>= 1
                bit += 1

            if idx < start + n:
                # ensure last -> first circular gap also >= mid
                if arr[start] + per - arr[idx] >= mid:
                    return True

        return False

    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        positions = sorted(self.get_1d_pos(x, y, side) for x, y in points)

        low, high = 0, 4 * side
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if self.can_place(mid, k, side, positions):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

